WITH combined AS (SELECT cs.cs_item_sk AS item_sk, p.p_promo_id AS promo_id, p.p_promo_name AS promo_name, 'Catalog' AS channel, SUM(cs.cs_net_profit) AS net_profit, SUM(cs.cs_net_paid) AS net_paid FROM catalog_sales cs JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk GROUP BY cs.cs_item_sk, p.p_promo_id, p.p_promo_name UNION ALL SELECT ws.ws_item_sk AS item_sk, p.p_promo_id AS promo_id, p.p_promo_name AS promo_name, 'Web' AS channel, SUM(ws.ws_net_profit) AS net_profit, SUM(ws.ws_net_paid) AS net_paid FROM web_sales ws JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk GROUP BY ws.ws_item_sk, p.p_promo_id, p.p_promo_name) SELECT item_sk, promo_id, promo_name, channel, net_profit, net_paid, net_profit / NULLIF(net_paid, 0) AS profit_margin, CASE WHEN net_profit / NULLIF(net_paid, 0) > 0.2 THEN 'High' ELSE 'Low' END AS profit_category, DENSE_RANK() OVER (PARTITION BY promo_id ORDER BY net_profit / NULLIF(net_paid, 0) DESC) AS profit_rank FROM combined WHERE net_paid IS NOT NULL ORDER BY promo_id, profit_rank LIMIT 100
